"""Input validation for signup-api (INC-5502, INTL-INPUT-014).

Rejects malformed or unsafe signup bodies BEFORE they reach the mail/account path. The email flows
into transactional mail headers (so CR/LF, control characters, or an over-length address is a
header-injection / abuse vector) and the display name flows into logs and templates (so control
characters are a log-injection vector).

International input is first-class (INTL-INPUT-014 review, see
docs/compliance/INTL-INPUT-014-disposition.md): non-ASCII local parts (EAI / SMTPUTF8, RFC 6530)
and non-ASCII (IDN) domains are accepted, as are display names in any script. What is rejected is
what is dangerous or structurally impossible - control characters, whitespace, CR/LF, missing or
repeated '@', empty domain labels - not what is merely non-ASCII. Well-formed ordinary addresses,
including plus-addressing and sub-domains, are accepted.
"""

MAX_TOTAL = 254           # RFC 5321 path limit; longer is an abuse vector, not a real user
MAX_LOCAL = 64            # max local-part length

# RFC 5321 "atext": printable ASCII allowed in a local part without quoting.
_ATEXT = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.!#$%&'*+/=?^_`{|}~-")


class ValidationError(ValueError):
    pass


def _has_controls(s):
    # C0 controls, DEL, and C1 controls: header/log-injection vectors, present in no
    # legitimate address or name in any script.
    return any(ord(c) < 32 or 127 <= ord(c) <= 159 for c in s)


def _ok_international(ch):
    # A non-ASCII character is acceptable if it is printable and not whitespace.
    return ch.isprintable() and not ch.isspace()


def _is_well_formed_email(addr):
    """Structural check for ordinary and internationalized addresses.

    Local part: RFC 5321 atext, or any printable non-whitespace non-ASCII char (EAI).
    Domain: two or more dot-separated non-empty labels of letters/digits/hyphens (Unicode IDN
    labels allowed), no leading/trailing hyphen.
    """
    local, sep, domain = addr.partition("@")
    if not sep or not local or not domain or "@" in domain:
        return False
    for ch in local:
        if ord(ch) < 128:
            if ch not in _ATEXT:
                return False
        elif not _ok_international(ch):
            return False
    labels = domain.split(".")
    if len(labels) < 2 or any(not label for label in labels):
        return False
    for label in labels:
        if label.startswith("-") or label.endswith("-"):
            return False
        for ch in label:
            if ord(ch) < 128:
                if not ch.isalnum() and ch != "-":
                    return False
            elif not _ok_international(ch):
                return False
    return True


def validate_signup(payload):
    email = payload.get("email", "").strip()
    name = payload.get("display_name", "")
    if not email or len(email) > MAX_TOTAL:
        raise ValidationError("email empty or too long")
    if _has_controls(email):
        raise ValidationError("email contains control characters (header-injection vector)")
    if not _is_well_formed_email(email):
        raise ValidationError("email is not a well-formed address")
    if len(email.split("@", 1)[0]) > MAX_LOCAL:
        raise ValidationError("email local-part too long")
    if _has_controls(name):
        raise ValidationError("display_name contains control characters (log-injection vector)")
    return {"email": email, "display_name": name.strip()}

